//! Parity with desktop/engine/hardware.py.
//!
//! `fixtures/parity_cases.json` is generated by `fixtures/gen_parity.py`,
//! which runs hardware.py's `select_profile_for` and `host_profile` on
//! fabricated machines. Every case is replayed here and must match field by
//! field, including the human-readable text.

use gm_probe::{
    host_profile_with, select_profile_with, Prefer, ProbeOptions, Profile, REFERENCE_TORCH,
};
use gm_types::{Arch, DeviceFacts, Gpu, Os, Vendor};
use serde_json::Value;

const CASES: &str = include_str!("fixtures/parity_cases.json");

fn os(s: &str) -> Os {
    match s {
        "windows" => Os::Windows,
        "macos" => Os::Macos,
        "linux" => Os::Linux,
        _ => Os::Other,
    }
}

fn arch(s: &str) -> Arch {
    match s {
        "x86_64" => Arch::X86_64,
        "arm64" => Arch::Arm64,
        _ => Arch::Other,
    }
}

fn vendor(s: &str) -> Vendor {
    match s {
        "nvidia" => Vendor::Nvidia,
        "intel" => Vendor::Intel,
        "amd" => Vendor::Amd,
        "apple" => Vendor::Apple,
        _ => Vendor::Other,
    }
}

fn opt_str(v: &Value) -> Option<String> {
    v.as_str().map(str::to_string)
}

/// hardware.py `HostFacts` (as_dict) → `DeviceFacts`.
fn facts(v: &Value) -> DeviceFacts {
    let gpus = v["gpus"]
        .as_array()
        .unwrap()
        .iter()
        .map(|g| Gpu {
            vendor: vendor(g["vendor"].as_str().unwrap()),
            name: g["name"].as_str().unwrap().to_string(),
            index: g["index"].as_u64().unwrap() as u32,
            compute_capability: g["compute_capability"].as_f64().map(|c| c as f32),
            driver: opt_str(&g["driver"]),
            memory_mb: g["memory_mb"].as_u64(),
            cores: g["cores"].as_u64().map(|c| c as u32),
            integrated: false,
        })
        .collect();
    DeviceFacts {
        os: os(v["os"].as_str().unwrap()),
        os_version: v["os_version"].as_str().unwrap().to_string(),
        arch: arch(v["arch"].as_str().unwrap()),
        translated: v["translated"].as_bool().unwrap(),
        hostname: v["hostname"].as_str().unwrap().to_string(),
        cpu_model: None,
        cpu_cores: v["cpu_count"].as_u64().map(|c| c as u32),
        ram_mb: v["ram_mb"].as_u64(),
        gpus,
        os_name_pretty: None,
    }
}

/// Compares one Rust profile with one Python profile; returns the mismatches.
fn diff(case: &str, which: &str, rust: &Profile, py: &Value) -> Vec<String> {
    let mut out = Vec::new();
    let mut check = |field: &str, ok: bool, r: String, p: String| {
        if !ok {
            out.push(format!("{case} [{which}] {field}: rust={r} python={p}"));
        }
    };
    let s = |k: &str| py[k].as_str().unwrap_or_default().to_string();
    check("port", rust.port == s("port"), rust.port.clone(), s("port"));
    check(
        "backend",
        rust.backend.as_str() == s("backend"),
        rust.backend.as_str().into(),
        s("backend"),
    );
    check(
        "label",
        rust.label == s("label"),
        rust.label.clone(),
        s("label"),
    );
    check(
        "reason",
        rust.reason == s("reason"),
        rust.reason.clone(),
        s("reason"),
    );
    check(
        "torch",
        rust.torch == s("torch"),
        rust.torch.clone(),
        s("torch"),
    );
    let reference = py["reference"].as_bool().unwrap();
    check(
        "reference",
        rust.reference == reference,
        rust.reference.to_string(),
        reference.to_string(),
    );
    let can_train = py["can_train"].as_bool().unwrap();
    check(
        "can_train",
        rust.can_train == can_train,
        rust.can_train.to_string(),
        can_train.to_string(),
    );
    // Python always carries an int (default 0); Rust leaves it None where no
    // single device is addressed (cpu, mps).
    let gpu_index = py["gpu_index"].as_u64().unwrap() as u32;
    check(
        "gpu_index",
        rust.gpu_index.unwrap_or(0) == gpu_index,
        format!("{:?}", rust.gpu_index),
        gpu_index.to_string(),
    );
    let gpu_name = opt_str(&py["gpu_name"]);
    check(
        "gpu_name",
        rust.gpu_name == gpu_name,
        format!("{:?}", rust.gpu_name),
        format!("{gpu_name:?}"),
    );
    let blocked = opt_str(&py["blocked"]);
    check(
        "blocked",
        rust.blocked == blocked,
        format!("{:?}", rust.blocked),
        format!("{blocked:?}"),
    );
    let fix = opt_str(&py["fix"]);
    check(
        "fix",
        rust.fix == fix,
        format!("{:?}", rust.fix),
        format!("{fix:?}"),
    );
    let warnings: Vec<String> = py["warnings"]
        .as_array()
        .unwrap()
        .iter()
        .map(|w| w.as_str().unwrap().to_string())
        .collect();
    check(
        "warnings",
        rust.warnings == warnings,
        format!("{:?}", rust.warnings),
        format!("{warnings:?}"),
    );
    out
}

/// Cases where Rust intentionally differs from hardware.py (QA 2026-11-24):
/// an x86_64 macOS process asking for `--prefer cpu`. Python hands out the
/// stock macOS wheel (port "mps"), which only exists for arm64, so the install
/// would fail; Rust blocks with the Intel-Mac / Rosetta explanation instead.
const DELIBERATE_DEVIATIONS: &[&str] = &["intel-mac/cpu", "rosetta/cpu"];

#[test]
fn matches_hardware_py() {
    let data: Value = serde_json::from_str(CASES).expect("parity_cases.json parses");
    assert_eq!(
        data["reference_torch"].as_str(),
        Some(REFERENCE_TORCH),
        "reference torch moved; regenerate"
    );
    let cases = data["cases"].as_array().unwrap();
    assert!(
        cases.len() >= 40,
        "expected at least 40 parity cases, got {}",
        cases.len()
    );

    // Experimental ROCm stays off: auto must behave exactly like Python.
    let options = ProbeOptions {
        experimental_rocm: false,
    };
    let mut failures = Vec::new();
    let mut deviations_seen = 0;
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let prefer: Prefer = case["prefer"].as_str().unwrap().parse().unwrap();
        let facts = facts(&case["facts"]);
        if DELIBERATE_DEVIATIONS.contains(&name) {
            // hardware.py returns an unblocked mps/cpu profile that cannot
            // install; Rust blocks it (both as worker and as host).
            deviations_seen += 1;
            let s = select_profile_with(&facts, prefer, &options);
            let h = host_profile_with(&facts, prefer, &options);
            if s.blocked.is_none() || h.blocked.is_none() {
                failures.push(format!("{name}: deliberate deviation no longer blocks"));
            }
            continue;
        }
        failures.extend(diff(
            name,
            "select",
            &select_profile_with(&facts, prefer, &options),
            &case["select"],
        ));
        failures.extend(diff(
            name,
            "host",
            &host_profile_with(&facts, prefer, &options),
            &case["host"],
        ));
    }
    assert_eq!(
        deviations_seen,
        DELIBERATE_DEVIATIONS.len(),
        "a deliberate deviation case vanished from the fixtures"
    );
    assert!(
        failures.is_empty(),
        "{} mismatches with hardware.py:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn every_port_and_block_is_covered() {
    let data: Value = serde_json::from_str(CASES).unwrap();
    let cases = data["cases"].as_array().unwrap();
    for port in [
        "cuda-cu130",
        "cuda-cu126",
        "cuda-cu128",
        "xpu",
        "mps",
        "cpu",
    ] {
        assert!(
            cases.iter().any(|c| c["select"]["port"] == port),
            "no parity case selects {port}"
        );
    }
    for prefer in Prefer::ALL {
        assert!(
            cases.iter().any(|c| c["prefer"] == prefer.as_str()),
            "no parity case prefers {prefer}"
        );
    }
    assert!(cases.iter().any(|c| !c["select"]["blocked"].is_null()));
    assert!(cases
        .iter()
        .any(|c| c["host"]["port"] == "cpu" && c["facts"]["os"] == "macos"));
}
